cy.request({
  method: 'POST',
  url: `${base}login`,
  failOnStatusCode: false,
  body: {
    username: 'ttt@test.fr',
    password: 'kjnfue'
  }
}).then(Response => {
  expect(Response.status).to.eq(401);
});

cy.request({
  method: 'POST',
  url: `${base}login`,
  body: {
    username,
    password
  }
}).then(Response => {
  expect(Response.status).to.eq(200);
  expect(Response.body).to.have.property('token');
  token = Response.body.token;
});

cy.request({
  method: 'GET',
  url: `${base}orders`,
  failOnStatusCode: false,
  body: {
    username: 'ttt@test.fr',
    password: 'kjnfue'
  }
}).then(Response => {
  expect(Response.status).to.eq(401);
});

cy.request({
  method: 'GET',
  url: `${base}products`
}).then(Response => {
  expect(Response.status).to.eq(200);
  expect(Response.body).to.be.an('array').and.to.have.length.greaterThan(0);
  productId = Response.body[0].id;
});

cy.request({
  method: 'GET',
  url: `${base}orders`,
  headers: {
    Authorization: `Bearer ${token}`
  }
}).then(Response => {
  expect(Response.status).to.eq(200);
  expect(Response.body).to.be.an('object').and.not.be.empty;
});

cy.request({
  method: 'POST',
  url: `${base}orders/add`,
  headers: {
    Authorization: `Bearer ${token}`
  },
  body: {
    product: productId,
    quantity: 1
  }
}).then(Response => {
  expect(Response.status).to.eq(200);
});

cy.request({
  method: 'POST',
  url: `${base}orders/add`,
  headers: {
    Authorization: `Bearer ${token}`
  },
  body: {
    product: 3,
    quantity: 5
  }
}).then(Response => {
  expect(Response.status).to.not.equal(200);
});

cy.request({
  method: 'POST',
  url: `${base}reviews`,
  headers: {
    Authorization: `Bearer ${token}`
  },
  body: {
    title: 'super',
    rating: 5,
    comment: 'super produit'
  }
}).then(Response => {
  expect(Response.status).to.eq(200);
  expect(Response.body).to.have.property('id');
  expect(Response.body).to.have.property('date');
  expect(Response.body).to.have.property('title', 'super');
  expect(Response.body).to.have.property('comment');
  expect(Response.body).to.have.property('rating');
  expect(Response.body).to.have.property('author');
});
